package backup

import (
	"slices"
	"testing"
)

// Promote takes every recovery setting out of postgresql.auto.conf, with
// pgBackRest's comment above them, and keeps everything else.
func TestWithoutRecoverySettings(t *testing.T) {
	raw := "# Do not edit this file manually!\n" +
		"# It will be overwritten by the ALTER SYSTEM command.\n" +
		"work_mem = '8MB'\n" +
		"\n" +
		"# Recovery settings generated by pgBackRest restore on 2026-10-15 09:31:02\n" +
		"restore_command = 'pgbackrest --pg1-path=/var/lib/postgresql/18/app --stanza=app-abc123 archive-get %f \"%p\"'\n" +
		"recovery_target_timeline = '3'\n" +
		"recovery_target_time='2026-10-15 09:30:00+00'\n" +
		"  recovery_target_action = 'pause'\n"
	kept, dropped := withoutRecoverySettings(raw)
	want := "# Do not edit this file manually!\n# It will be overwritten by the ALTER SYSTEM command.\nwork_mem = '8MB'\n\n"
	if kept != want {
		t.Errorf("kept:\n%s", kept)
	}
	if !slices.Equal(dropped, []string{"restore_command", "recovery_target_timeline", "recovery_target_time", "recovery_target_action"}) {
		t.Errorf("dropped %v", dropped)
	}
	if kept, dropped := withoutRecoverySettings(want); kept != want || len(dropped) != 0 {
		t.Errorf("a clean file changed: %q %v", kept, dropped)
	}
}

// Only a pending restart for a recovery setting is the promote's to settle.
func TestRecoveryOnly(t *testing.T) {
	got := recoveryOnly([]string{"recovery_target_timeline", "shared_buffers", "recovery_target_action"})
	if !slices.Equal(got, []string{"recovery_target_timeline", "recovery_target_action"}) {
		t.Errorf("recovery settings %v", got)
	}
	if recoveryOnly([]string{"shared_buffers"}) != nil {
		t.Error("another setting's pending restart was taken for the promote's")
	}
}
